const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  try {
    // 1. Geometry & Time Definitions
    // Hôtel de Ville, Paris (approximate location for marathon starting line)
    const parisPoint = ee.Geometry.Point([2.3522, 48.8566]);
    // Fausses-Reposes forest near Versailles (approximate center)
    const forestPoint = ee.Geometry.Point([2.1469, 48.8155]);

    // Create small buffers for aggregation due to 1km resolution of MODIS
    const parisBuffer = parisPoint.buffer(500); // 500m buffer
    const forestBuffer = forestPoint.buffer(500); // 500m buffer

    // Date and time
    // August 6, 2024, 1:40 PM local time (Paris, CET/CEST is UTC+2 in August)
    // 13:40 - 2 hours = 11:40 UTC
    const date = '2024-08-06';
    const startTimeUtc = ee.Date(date).advance(11, 'hour').advance(40, 'minute');
    const endTimeUtc = startTimeUtc.advance(30, 'minute'); // +/- 30 min window

    // 2. Data Acquisition & Check
    // MODIS Aqua Land Surface Temperature and Emissivity (MYD11A1) for daytime LST
    // Aqua overpass is typically around 1:30 PM local time.
    let l_col = ee.ImageCollection('MODIS/061/MYD11A1')
      .filterDate(startTimeUtc, endTimeUtc)
      .select(['LST_Day_1km', 'QC_Day']);

    let colSize = await l_col.size().getInfo();
    if (colSize === 0) {
      console.log("No MODIS Aqua LST images found for 2024-08-06 around 1:40 PM local time. Trying wider time window.");
      // Widen time window slightly
      const widerStartTimeUtc = ee.Date(date).advance(10, 'hour').advance(40, 'minute');
      const widerEndTimeUtc = ee.Date(date).advance(12, 'hour').advance(40, 'minute');
      l_col = ee.ImageCollection('MODIS/061/MYD11A1')
        .filterDate(widerStartTimeUtc, widerEndTimeUtc)
        .select(['LST_Day_1km', 'QC_Day']);
      colSize = await l_col.size().getInfo();
    }

    if (colSize === 0) {
      console.log("No MODIS Aqua LST data for the specified date and time window.");
      console.log("C1");
      return;
    }

    // 3. Processing - Cloud Masking and LST Extraction
    // Function to mask clouds and scale LST
    const maskAndScaleLST = function(image) {
      const lst = image.select('LST_Day_1km');
      const qc = image.select('QC_Day');

      // MODIS LST quality bits (0-1: LST Quality):
      // 00 (0): Good quality LST (produced)
      // 01 (1): LST produced, but may be of lower quality, check other QA
      // 10 (2): Emissivity error
      // 11 (3): LST not produced due to cloud
      // We want to keep 00 (0) or 01 (1).
      const goodQuality = qc.bitwiseAnd(3).lte(1); // Keep pixels where LST Quality is 0 or 1

      // Apply scale factor (0.02) and convert to Celsius (from Kelvin)
      const scaledLST = lst.multiply(0.02).subtract(273.15); // K to C

      return scaledLST.updateMask(goodQuality).rename('LST_C');
    };

    const maskedLST = l_col.map(maskAndScaleLST).mean(); // Take the mean of available images for the period

    // Check if the image has data after processing
    const hasDataParis = await maskedLST.reduceRegion({
      reducer: ee.Reducer.count(),
      geometry: parisBuffer,
      scale: 1000,
      maxPixels: 1e9
    }).get('LST_C').getInfo();

    const hasDataForest = await maskedLST.reduceRegion({
      reducer: ee.Reducer.count(),
      geometry: forestBuffer,
      scale: 1000,
      maxPixels: 1e9
    }).get('LST_C').getInfo();

    if (hasDataParis === 0 || hasDataForest === 0) {
      console.log(`Paris valid pixels: ${hasDataParis}, Forest valid pixels: ${hasDataForest}`);
      console.log("No valid pixels remaining after cloud masking for one or both locations.");
      console.log("C2");
      return;
    }

    // 4. Calculation
    const parisLST = await maskedLST.reduceRegion({
      reducer: ee.Reducer.mean(),
      geometry: parisBuffer,
      scale: 1000, // MODIS resolution is 1km
      maxPixels: 1e9
    }).get('LST_C').getInfo();

    const forestLST = await maskedLST.reduceRegion({
      reducer: ee.Reducer.mean(),
      geometry: forestBuffer,
      scale: 1000,
      maxPixels: 1e9
    }).get('LST_C').getInfo();

    // 5. Validation & Final Answer
    if (parisLST === null || isNaN(parisLST) || forestLST === null || isNaN(forestLST)) {
      console.log(`Paris LST: ${parisLST}, Forest LST: ${forestLST}`);
      console.log("Calculation resulted in Null or NaN for one or both LST values.");
      console.log("C3");
      return;
    }

    console.log(`Paris (Hôtel de Ville) LST: ${parisLST.toFixed(2)} °C (Pixels: ${hasDataParis})`);
    console.log(`Fausses-Reposes Forest LST: ${forestLST.toFixed(2)} °C (Pixels: ${hasDataForest})`);

    if (parisLST < forestLST) {
      console.log("A");
    } else {
      console.log("B");
    }

  } catch (e) {
    console.error("An error occurred during analysis: ", e);
    console.log("D"); // General error
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
